CREATE POLICY portraits_public_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='member-portraits');
CREATE POLICY portraits_editor_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='member-portraits' AND public.is_admin() AND storage.extension(name) IN ('jpg','jpeg','png','webp'));
CREATE POLICY portraits_editor_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='member-portraits' AND public.is_admin());
CREATE TABLE public.club_forms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scope_key text NOT NULL UNIQUE,event_id uuid REFERENCES public.events(id) ON DELETE CASCADE,title text NOT NULL DEFAULT '',fields jsonb NOT NULL DEFAULT '[]',is_published boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.club_forms TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.club_forms TO authenticated; GRANT ALL ON public.club_forms TO service_role; ALTER TABLE public.club_forms ENABLE ROW LEVEL SECURITY;
CREATE POLICY forms_public ON public.club_forms FOR SELECT TO anon,authenticated USING(is_published AND (event_id IS NULL OR EXISTS(SELECT 1 FROM public.events WHERE id=event_id AND status='published')));
CREATE POLICY forms_reader ON public.club_forms FOR SELECT TO authenticated USING(public.can_read_admin()); CREATE POLICY forms_editor ON public.club_forms FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.form_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),form_id uuid REFERENCES public.club_forms(id) ON DELETE SET NULL,event_id uuid REFERENCES public.events(id) ON DELETE CASCADE,title_snapshot text NOT NULL,fields_snapshot jsonb NOT NULL,revision integer NOT NULL,answers jsonb NOT NULL,status text NOT NULL DEFAULT 'received',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.form_submissions TO authenticated; GRANT ALL ON public.form_submissions TO service_role; ALTER TABLE public.form_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY submissions_reader ON public.form_submissions FOR SELECT TO authenticated USING(public.can_read_admin()); CREATE POLICY submissions_update ON public.form_submissions FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin()); CREATE POLICY submissions_delete ON public.form_submissions FOR DELETE TO authenticated USING(public.is_admin());
CREATE INDEX submissions_event_idx ON public.form_submissions(event_id,status);
CREATE FUNCTION public.validate_club_form() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE f jsonb; ids text[]:=ARRAY[]::text[]; typ text; BEGIN
IF jsonb_typeof(NEW.fields)<>'array' OR jsonb_array_length(NEW.fields)>50 OR length(NEW.title)>200 OR (NEW.scope_key='membership' AND NEW.event_id IS NOT NULL) OR (NEW.scope_key<>'membership' AND (NEW.event_id IS NULL OR NEW.scope_key<>'event:'||NEW.event_id::text)) THEN RAISE EXCEPTION 'INVALID_FORM'; END IF;
FOR f IN SELECT value FROM jsonb_array_elements(NEW.fields) LOOP typ:=f->>'type';
IF typ IS NULL OR typ NOT IN ('heading','paragraph','text','textarea','email','tel','number','date','select','radio','checkbox','accommodation') OR coalesce(f->>'id','') !~ '^[A-Za-z0-9_-]{1,80}$' OR f->>'id'=ANY(ids) OR length(coalesce(f->>'label','')) NOT BETWEEN 1 AND 300 OR jsonb_typeof(f->'required') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'INVALID_FIELD'; END IF;
IF typ IN ('select','radio') THEN IF jsonb_typeof(f->'options') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_OPTIONS'; END IF; IF jsonb_array_length(f->'options') NOT BETWEEN 1 AND 30 OR EXISTS(SELECT 1 FROM jsonb_array_elements(f->'options') o WHERE jsonb_typeof(o)<>'string' OR length(o#>>'{}') NOT BETWEEN 1 AND 200) THEN RAISE EXCEPTION 'INVALID_OPTIONS'; END IF; END IF;
ids:=array_append(ids,f->>'id'); END LOOP;
IF NEW.is_published AND (length(trim(NEW.title))=0 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.fields) f WHERE f->>'type' NOT IN ('heading','paragraph'))) THEN RAISE EXCEPTION 'EMPTY_FORM'; END IF;
IF TG_OP='UPDATE' THEN NEW.revision:=OLD.revision+1; ELSE NEW.revision:=1; END IF; NEW.updated_at:=now(); RETURN NEW; END; $$;
CREATE TRIGGER validate_club_form BEFORE INSERT OR UPDATE ON public.club_forms FOR EACH ROW EXECUTE FUNCTION public.validate_club_form();
CREATE FUNCTION public.submit_club_form(p_form_id uuid,p_revision integer,p_answers jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE frm public.club_forms; ev public.events; f jsonb; v jsonb; txt text; typ text; result text:='received'; n bigint; key text;
BEGIN SELECT * INTO frm FROM public.club_forms WHERE id=p_form_id AND is_published FOR SHARE; IF NOT FOUND OR frm.revision<>p_revision THEN RAISE EXCEPTION 'FORM_UNAVAILABLE'; END IF;
IF jsonb_typeof(p_answers) IS DISTINCT FROM 'object' OR octet_length(p_answers::text)>100000 THEN RAISE EXCEPTION 'INVALID_ANSWERS'; END IF;
FOR key IN SELECT jsonb_object_keys(p_answers) LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(frm.fields) f WHERE f->>'id'=key AND f->>'type' NOT IN ('heading','paragraph')) THEN RAISE EXCEPTION 'INVALID_FIELD'; END IF; END LOOP;
FOR f IN SELECT value FROM jsonb_array_elements(frm.fields) LOOP typ:=f->>'type'; IF typ IN ('heading','paragraph') THEN CONTINUE; END IF; v:=p_answers->(f->>'id'); txt:=coalesce(v#>>'{}','');
IF typ='accommodation' THEN
IF v IS NULL OR jsonb_typeof(v) IS DISTINCT FROM 'object' OR jsonb_typeof(v->'needed') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'INVALID_ACCOMMODATION'; END IF;
IF (v->>'needed')::boolean AND (length(trim(coalesce(v->>'residence',''))) NOT BETWEEN 2 AND 120 OR coalesce(v->>'bac','') !~ '^[0-9]{1,30}$' OR coalesce(v->>'phone','') !~ '^\+?[0-9 ()-]{6,25}$') THEN RAISE EXCEPTION 'INVALID_ACCOMMODATION'; END IF;
IF NOT (v->>'needed')::boolean THEN p_answers:=jsonb_set(p_answers,ARRAY[f->>'id'],jsonb_build_object('needed',false,'residence',NULL,'bac',NULL,'phone',NULL)); END IF;
ELSIF typ='checkbox' THEN IF v IS NOT NULL AND jsonb_typeof(v) IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'INVALID_FIELD'; END IF; IF (f->>'required')::boolean AND v IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'REQUIRED_FIELD'; END IF;
ELSE IF v IS NOT NULL AND jsonb_typeof(v) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'INVALID_FIELD'; END IF; IF (f->>'required')::boolean AND length(trim(txt))=0 THEN RAISE EXCEPTION 'REQUIRED_FIELD'; END IF; IF length(txt)>4000 THEN RAISE EXCEPTION 'INVALID_FIELD'; END IF;
IF txt<>'' THEN IF typ='email' AND txt !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'INVALID_EMAIL'; END IF; IF typ='number' AND txt !~ '^-?[0-9]+(\.[0-9]+)?$' THEN RAISE EXCEPTION 'INVALID_NUMBER'; END IF; IF typ='date' THEN BEGIN PERFORM txt::date; EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'INVALID_DATE'; END; END IF; IF typ IN ('select','radio') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(f->'options') o WHERE o=txt) THEN RAISE EXCEPTION 'INVALID_OPTION'; END IF; END IF; END IF; END LOOP;
PERFORM public.check_rate_limit('custom-form:'||p_form_id::text||':'||coalesce(inet_client_addr()::text,'visitor'),60,interval '1 hour');
IF frm.event_id IS NOT NULL THEN SELECT * INTO ev FROM public.events WHERE id=frm.event_id FOR UPDATE; IF NOT FOUND OR ev.status<>'published' OR NOT ev.registration_open OR coalesce(ev.ends_at,ev.starts_at)<now() THEN RAISE EXCEPTION 'EVENT_UNAVAILABLE'; END IF;
SELECT (SELECT count(*) FROM public.event_registrations WHERE event_id=ev.id AND status='confirmed')+(SELECT count(*) FROM public.form_submissions WHERE event_id=ev.id AND status='confirmed') INTO n;
result:=CASE WHEN ev.capacity IS NOT NULL AND n>=ev.capacity THEN 'waitlisted' ELSE 'confirmed' END; END IF;
INSERT INTO public.form_submissions(form_id,event_id,title_snapshot,fields_snapshot,revision,answers,status) VALUES(frm.id,frm.event_id,frm.title,frm.fields,frm.revision,p_answers,result); RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.submit_club_form(uuid,integer,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_club_form(uuid,integer,jsonb) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.get_event_seat_counts() RETURNS TABLE(event_id uuid,confirmed_count integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT e.id, ((SELECT count(*) FROM public.event_registrations r WHERE r.event_id=e.id AND r.status='confirmed')+(SELECT count(*) FROM public.form_submissions s WHERE s.event_id=e.id AND s.status='confirmed'))::integer FROM public.events e WHERE e.status='published'; $$;